'use strict';
(()=>{
const side=document.querySelector('aside nav'),anchor=[...side.querySelectorAll('button')].find(b=>b.textContent.trim()==='Частота');const nav=document.createElement('button');nav.innerHTML='<svg class="icon" aria-hidden="true"><use href="icons.svg#list"></use></svg><span>Журнал действий</span>';anchor.after(nav);
const page=document.createElement('main');page.id='action-journal-page';page.hidden=true;page.innerHTML=`<div class="breadcrumb">Коммуникации / Журнал действий</div><div class="heading"><div><h1>Журнал действий</h1><p>Кто и когда изменил рассылку или её запуск</p></div><button class="outline" id="aj-refresh">Обновить</button></div><div class="demo"><b>Без отправки</b><span>Здесь действия операторов и системы. Сбор контактов остаётся в разделе «Журнал», а доставки и переходы — в статистике. История начинается с подключения этого журнала; старые действия и их авторы не восстанавливаются.</span></div><p role="status" id="aj-status"></p>
<section class="panel"><h2>Текущий оператор</h2><p id="aj-identity"></p><form id="aj-operator"><label>Локальная метка оператора<input id="aj-name" maxlength="120" autocomplete="off" required></label><button class="outline">Сохранить метку</button></form><p>Новые действия подписываются учётной записью пользователя. Старые записи сохраняют исходные метки и не переименовываются. Локальная метка не заменяет подтверждённый вход.</p></section>
<section class="panel"><h2>История</h2><form id="aj-filters" class="aj-grid"><label>Поиск по названию и описанию<input id="aj-query" type="search" maxlength="180"></label><label>Оператор<select id="aj-actor"><option value="">Все операторы</option></select></label><label>Действие<select id="aj-action"><option value="">Все действия</option></select></label><label>Объект<select id="aj-object_type"><option value="">Все объекты</option></select></label><label>ID объекта<input id="aj-object_id" type="number" min="1" step="1"></label><label>ID связанной рассылки<input id="aj-campaign_id" type="number" min="1" step="1"></label><label>Результат<select id="aj-result"><option value="">Все результаты</option></select></label><label>С даты<input id="aj-from" type="date"></label><label>По дату включительно<input id="aj-to" type="date"></label><label>Порядок<select id="aj-direction"><option value="desc">Сначала новые</option><option value="asc">Сначала старые</option></select></label><button class="outline">Применить фильтры</button><button class="outline" type="button" id="aj-reset">Сбросить</button></form><p>Даты фильтра — фактическое время записи (Asia/Qyzylorda). Виртуальная дата имитации, если есть, указана в подробностях. GET и обычные обновления страницы не создают записей.</p><div class="table-scroll" id="aj-table"></div><div class="actions"><button class="outline" id="aj-prev">Назад</button><span id="aj-pagination"></span><button class="outline" id="aj-next">Далее</button></div></section>
<section class="panel" id="aj-detail" hidden><div class="section-title"><h2>Подробности действия</h2><button class="outline" id="aj-close-detail">Закрыть подробности</button></div><p id="aj-detail-note"></p><div class="aj-snapshots"><div><h3>До</h3><pre id="aj-before"></pre></div><div><h3>После</h3><pre id="aj-after"></pre></div></div><p>В снимках — поля настройки, версии и состояния. Тексты HTML, пароли, токены и адреса получателей сюда не копируются. Изменить или удалить записи через интерфейс/API нельзя.</p></section>`;
document.body.append(page);const $=id=>document.getElementById('aj-'+id);const keys=['query','actor','action','object_type','object_id','campaign_id','result','from','to','direction'];let current=null,busy=false,number=1,generation=0;
const sourceLabels={authenticated:'Учётная запись',remote_user:'Серверная учётная запись',declared:'Самоуказанная метка',anonymous:'Без авторизации',system:'Система'};
function text(tag,value){const el=document.createElement(tag);el.textContent=value??'';return el;}
function date(v){return new Date(v).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'});}
function options(id,values,label){const selected=$(id).value;$(id).replaceChildren(new Option(label,''));for(const [key,value]of Object.entries(values))$(id).add(new Option(value,key));$(id).value=selected;}
function controls(){for(const el of page.querySelectorAll('button,input,select'))el.disabled=busy;const verified=['authenticated','remote_user'].includes(current?.current_actor.source);$('operator').hidden=verified;for(const el of $('operator').querySelectorAll('input,button'))el.disabled=busy||verified;$('prev').disabled=busy||!current||number<=1;$('next').disabled=busy||!current||number>=current.pagination.pages;}
function detail(row){$('detail').hidden=false;$('detail-note').textContent=`Запись #${row.id} · ${row.actor.label} (${sourceLabels[row.actor.source]||row.actor.source}) · ${date(row.occurred_at)} · ID запроса: ${row.request_id||'служебный вызов без HTTP'}. Связанные рассылки: ${row.campaign_ids.join(', ')||'нет'}.`;$('before').textContent=JSON.stringify(row.before,null,2);$('after').textContent=JSON.stringify(row.after,null,2);$('detail').scrollIntoView({block:'start'});}
async function load(){const seq=++generation,params=new URLSearchParams({page:String(number)});for(const key of keys)if($(key).value)params.set(key,$(key).value);const d=await api('/api/action-journal?'+params);if(seq!==generation)return;current=d;number=d.pagination.page;options('action',d.actions,'Все действия');options('object_type',d.object_types,'Все объекты');options('result',d.results,'Все результаты');const selected=$('actor').value;$('actor').replaceChildren(new Option('Все операторы',''));for(const a of d.actors)$('actor').add(new Option(`${a.actor_label} · ${sourceLabels[a.actor_source]||a.actor_source}`,a.actor_key));$('actor').value=selected;$('identity').textContent=`${d.current_actor.label} · ${sourceLabels[d.current_actor.source]||d.current_actor.source} · ${d.current_actor.key}`;
const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr'),labels=['Время','Кто','Действие','Объект','Результат','Описание'];labels.forEach(h=>tr.append(text('th',h)));head.append(tr);table.append(head);const body=document.createElement('tbody');for(const r of d.events){const row=document.createElement('tr'),who=document.createElement('div');who.append(text('strong',r.actor.label),text('small',sourceLabels[r.actor.source]||r.actor.source));if(r.initiated_by?.label)who.append(text('small','Инициатор: '+r.initiated_by.label));const note=document.createElement('div');note.append(text('p',r.summary));const button=text('button','Подробности');button.className='outline';button.onclick=()=>detail(r);note.append(button);const cells=[date(r.occurred_at),who,d.actions[r.action]||r.action,`${d.object_types[r.object_type]||r.object_type} #${r.object_id||'—'} · ${r.object_label}`,d.results[r.result]||r.result,note];cells.forEach((v,i)=>{const td=document.createElement('td');td.dataset.label=labels[i];if(v instanceof Node)td.append(v);else td.textContent=v;row.append(td);});body.append(row);}table.append(body);$('table').replaceChildren(table);if(!d.events.length)$('table').append(text('p','Действий по выбранным фильтрам нет.'));$('pagination').textContent=`${number} / ${d.pagination.pages} · записей: ${d.pagination.total}`;controls();}
async function mutate(fn){if(busy)return;busy=true;controls();$('status').textContent='';try{await fn();}catch(e){$('status').textContent=e.message;}finally{busy=false;controls();}}
$('operator').onsubmit=e=>{e.preventDefault();mutate(async()=>{await api('/api/action-journal/operator',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('name').value})});await load();$('status').textContent='Метка сохранена. Новые действия будут отмечены ею; прежние записи сохраняют исходного автора.';});};$('filters').onsubmit=e=>{e.preventDefault();number=1;$('detail').hidden=true;mutate(load);};$('refresh').onclick=()=>mutate(load);$('reset').onclick=()=>{for(const key of keys)$(key).value=key==='direction'?'desc':'';number=1;mutate(load);};$('prev').onclick=()=>mutate(async()=>{number--;await load();});$('next').onclick=()=>mutate(async()=>{number++;await load();});$('close-detail').onclick=()=>{$('detail').hidden=true;};
function open(campaignId){document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;side.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===nav));if(campaignId){$('campaign_id').value=String(campaignId);number=1;}sessionStorage.setItem('open-action-journal','1');document.title='Журнал действий';mutate(load);}
nav.onclick=()=>open();side.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&b!==nav){page.hidden=true;generation++;sessionStorage.removeItem('open-action-journal');}});window.ActionJournal={open,openTarget(target){for(const key of keys)$(key).value=key==='direction'?'desc':'';$('object_type').value=target.object_type==='source'?'':target.object_type||'';$('object_id').value=target.object_id||'';if(target.campaign_id)$('campaign_id').value=String(target.campaign_id);number=1;open();}};for(const id of ['automation-page','rehearsal-page']){const host=document.getElementById(id)?.querySelector('.heading');if(host){const b=text('button','Журнал действий');b.className='outline';b.onclick=()=>open();host.append(b);}}if(sessionStorage.getItem('open-action-journal'))open();
})();
